export const CONSULT_SCHEDULE_DAY_COUNT = 7;
export const CONSULT_SCHEDULE_ALL_KEY = 'all';

export interface ConsultScheduleDay {
  dateKey: string;
  dayOfMonth: number;
  isToday: boolean;
  weekdayIndex: number;
}

const padDatePart = (value: number): string => String(value).padStart(2, '0');

const startOfLocalDay = (entryDate: Date): Date =>
  new Date(entryDate.getFullYear(), entryDate.getMonth(), entryDate.getDate());

export const formatConsultScheduleDateKey = (date: Date): string =>
  `${date.getFullYear()}-${padDatePart(date.getMonth() + 1)}-${padDatePart(
    date.getDate(),
  )}`;

export const buildConsultScheduleDays = (
  entryDate: Date,
): ConsultScheduleDay[] => {
  const start = startOfLocalDay(entryDate);

  return Array.from(
    { length: CONSULT_SCHEDULE_DAY_COUNT },
    (_value, offset): ConsultScheduleDay => {
      const date = new Date(start);
      date.setDate(start.getDate() + offset);

      return {
        dateKey: formatConsultScheduleDateKey(date),
        dayOfMonth: date.getDate(),
        isToday: offset === 0,
        weekdayIndex: date.getDay(),
      };
    },
  );
};

import React, { useMemo, useState } from 'react';
import { ScrollView, TouchableOpacity, View } from 'react-native';

import AppText from '@components/app-text/app-text';
import constants from '@constants';

import {
  CONSULT_SCHEDULE_ALL_KEY,
  buildConsultScheduleDays,
  type ConsultScheduleDay,
} from './consult-schedule-days';
import styles from './consult-screen.styles';

const WEEKDAY_KEYS = [
  'consult_schedule.weekday_0',
  'consult_schedule.weekday_1',
  'consult_schedule.weekday_2',
  'consult_schedule.weekday_3',
  'consult_schedule.weekday_4',
  'consult_schedule.weekday_5',
  'consult_schedule.weekday_6',
] as const;

interface ConsultScheduleStripProps {
  entryDate?: Date;
}

const getWeekdayLabel = (weekdayIndex: number): string =>
  constants.i18n.t(WEEKDAY_KEYS[weekdayIndex] ?? WEEKDAY_KEYS[0]);

const ConsultScheduleStrip = ({
  entryDate,
}: ConsultScheduleStripProps): React.ReactElement => {
  const [anchorDate] = useState<Date>(() => entryDate ?? new Date());
  const [selectedKey, setSelectedKey] = useState<string>(
    CONSULT_SCHEDULE_ALL_KEY,
  );
  const days = useMemo(
    (): ConsultScheduleDay[] => buildConsultScheduleDays(anchorDate),
    [anchorDate],
  );
  const allLabel = constants.i18n.t('consult_schedule.all');
  const todayLabel = constants.i18n.t('consult_schedule.today');

  return (
    <ScrollView
      contentContainerStyle={styles.scheduleStripContent}
      horizontal
      showsHorizontalScrollIndicator={false}
      style={styles.scheduleStrip}
      testID="consult-schedule-strip"
    >
      <TouchableOpacity
        accessible
        accessibilityLabel={allLabel}
        accessibilityRole="button"
        accessibilityState={{ selected: selectedKey === CONSULT_SCHEDULE_ALL_KEY }}
        activeOpacity={0.8}
        onPress={(): void => setSelectedKey(CONSULT_SCHEDULE_ALL_KEY)}
        style={[
          styles.scheduleChip,
          styles.scheduleAllChip,
          selectedKey === CONSULT_SCHEDULE_ALL_KEY && styles.scheduleChipSelected,
        ]}
        testID="consult-schedule-all"
      >
        <AppText
          style={[
            styles.scheduleAllText,
            selectedKey === CONSULT_SCHEDULE_ALL_KEY &&
              styles.scheduleChipTextSelected,
          ]}
        >
          {allLabel}
        </AppText>
        {selectedKey === CONSULT_SCHEDULE_ALL_KEY ? (
          <View style={styles.scheduleChipFold} />
        ) : null}
      </TouchableOpacity>
      {days.map(
        (day: ConsultScheduleDay): React.ReactElement => {
          const selected = selectedKey === day.dateKey;
          const weekdayLabel = day.isToday
            ? todayLabel
            : getWeekdayLabel(day.weekdayIndex);
          const dayLabel = String(day.dayOfMonth);

          return (
            <TouchableOpacity
              accessible
              accessibilityLabel={`${weekdayLabel} ${dayLabel}`}
              accessibilityRole="button"
              accessibilityState={{ selected }}
              activeOpacity={0.8}
              key={day.dateKey}
              onPress={(): void => setSelectedKey(day.dateKey)}
              style={[
                styles.scheduleChip,
                selected && styles.scheduleChipSelected,
              ]}
              testID={`consult-schedule-day-${day.dateKey}`}
            >
              <AppText
                style={[
                  styles.scheduleWeekday,
                  selected && styles.scheduleChipTextSelected,
                ]}
              >
                {weekdayLabel}
              </AppText>
              <AppText
                style={[
                  styles.scheduleDayNumber,
                  selected && styles.scheduleChipTextSelected,
                ]}
              >
