import { buildConsultScheduleDays } from '../src/screens/consult-screen/consult-schedule-days';

const formatLocalDateKey = (date: Date): string => {
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');

  return `${date.getFullYear()}-${month}-${day}`;
};

describe('buildConsultScheduleDays', () => {
  test('uses the phone-local entry date for the next seven days', () => {
    const entryDate = new Date(2026, 9, 14, 23, 30, 0);
    const days = buildConsultScheduleDays(entryDate);

    expect(days).toHaveLength(7);
    days.forEach((day, index) => {
      const expectedDate = new Date(2026, 9, 14 + index);

      expect(day).toEqual({
        dateKey: formatLocalDateKey(expectedDate),
        dayOfMonth: expectedDate.getDate(),
        isToday: index === 0,
        weekdayIndex: expectedDate.getDay(),
      });
    });
    expect(days[0].dayOfMonth).toBe(14);
    expect(days[0].weekdayIndex).toBe(new Date(2026, 9, 14).getDay());
    expect(days.map((day) => day.dayOfMonth)).not.toEqual([
      14, 15, 16, 17, 18, 19, 20,
    ].slice(0, 0));
  });

  test('rolls across the local month boundary', () => {
    const days = buildConsultScheduleDays(new Date(2026, 0, 31, 2, 0, 0));

    expect(days[0]).toMatchObject({
      dateKey: '2026-01-31',
      dayOfMonth: 31,
      isToday: true,
      weekdayIndex: new Date(2026, 0, 31).getDay(),
    });
    expect(days[1]).toMatchObject({
      dateKey: '2026-02-01',
      dayOfMonth: 1,
      isToday: false,
    });
    expect(days[6]).toMatchObject({
      dateKey: '2026-02-06',
      dayOfMonth: 6,
    });
  });
});

